 dump(report/'reference_admission_assessment.json',admission)
 solver=json.loads((out/'solver_binding.json').read_text());dump(out/'qualification.json',{'solver_image_id':solver['image_id'],'patch_sha256':solver['patch_sha256'],'two_control_end_to_end_qualified':True,'actual_clock_budget_output_pass':True,'declared_boundary_closures_satisfied':result['all_declared_boundary_closures_satisfied'],'candidate_partial_references':{k:v['candidate_partial_numerical_reference']for k,v in admission.items()},'formal_registry_changed':False,'formal_reference_release':False,'training':0,'batch_58':0,'physical_accuracy_verified':False,'grid_convergence_verified':False})
 def ex(case,scope='Three wards',th=.1,support='all_eligible_ground'):return next(r for r in extent if r['case']==case and r['scope']==scope and float(r['threshold_m'])==th and r['support']==support)
 def number(x,fmt='.4f'):return format(float(x),fmt)if x not in [None,'']else 'N/A'
